<script setup>
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { portalRequest, setCsrf } from './api.js';
import WebsitePages from './components/WebsitePages.vue';
import DocsCenter from './components/DocsCenter.vue';
import ProvisioningPanel from './components/ProvisioningPanel.vue';
import { parsePortalHash, publicPages } from './portal-navigation.js';

const route = ref(parsePortalHash(location.hash).page);
const documentRoute = ref(parsePortalHash(location.hash));
const catalog = ref({ plans: [], environment: 'sandbox' }); const workspace = ref(null); const admin = ref(null);
const busy = ref(false); const alert = ref(''); const notice = ref(''); const menuOpen = ref(false);
const tenantId = ref(''); const tenant = computed(() => workspace.value?.tenants.find(t => t.id === tenantId.value));
const canManage = computed(() => ['owner', 'admin'].includes(tenant.value?.role));
const auth = ref({ name: '', email: '', password: '', acceptedTerms: false });
const tenantForm = ref({ name: '', slug: '', requestId: crypto.randomUUID() });
const invite = ref({ email: '', role: 'member' }); const inviteToken = ref(''); const acceptToken = ref('');
const billing = ref({ kind: 'subscription', planId: 'professional', amount: '100', couponCode: '' });
const price = ref(null); const selectedOrder = ref(null); const payMethod = ref('sandbox'); const payAcknowledged = ref(false);
let orderRequestId = crypto.randomUUID();
const coupon = ref({ code: '', type: 'fixed', value: '10', min: '0', maxUses: 100, days: 30, planId: '' });
const tenantOrders = computed(() => workspace.value?.orders.filter(o => o.tenantId === tenantId.value) || []);
const tenantLedger = computed(() => workspace.value?.ledger.filter(l => l.tenantId === tenantId.value) || []);
const isConsole = computed(() => ['console', 'billing', 'team', 'admin'].includes(route.value));
const money = cents => new Intl.NumberFormat('zh-CN', { style: 'currency', currency: 'CNY' }).format((cents || 0) / 100);
const date = value => value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '—';
const status = value => ({ provisioning_pending: '待开通', sandbox_ready: '测试空间已开通', suspended: '已停用', active: '正常', pending: '待支付', paid: '测试支付完成', cancelled: '已取消', expired: '已过期' }[value] || value);
const roleName = value => ({ owner: '所有者', admin: '管理员', member: '成员' }[value] || value);
const errors = { AUTH_REQUIRED: '请先登录，或重新登录已失效的会话。', LOGIN_FAILED: '邮箱、密码或账号状态不正确。', PASSWORD_POLICY: '密码长度需为12至128位。', TERMS_REQUIRED: '请先阅读并同意测试服务说明。', REGISTRATION_UNAVAILABLE: '暂时无法注册，请检查邮箱是否已使用。', EMAIL_INVALID: '请输入有效的邮箱地址。', INVALID_INPUT: '请检查填写的信息。', INVALID_AMOUNT: '请输入有效金额或数量。', SLUG_INVALID: '空间标识需3至40位，以字母开头，仅支持小写字母、数字和短横线。', SLUG_TAKEN: '该空间标识已被使用。', TENANT_NOT_FOUND: '该空间不存在或你没有访问权限。', TENANT_PERMISSION_DENIED: '当前租户角色不允许此操作。', ADMIN_REQUIRED: '此功能仅限平台管理员。', COUPON_UNAVAILABLE: '优惠券不存在、已过期、名额已占用或不适用。', COUPON_NOT_APPLICABLE: '充值不支持使用优惠券。', COUPON_EXISTS: '此优惠券代码已存在。', COUPON_DATE_INVALID: '请检查优惠券有效期。', PLAN_CHANGE_REQUIRES_REVIEW: '有效会员目前仅支持同套餐续费；跨套餐变更需另行处理。', INSUFFICIENT_BALANCE: '测试余额不足，请先完成测试充值。', PAYMENT_NOT_CONFIGURED: '支付通道未开启，没有扣款或到账。', CSRF_REJECTED: '页面会话已更新，请刷新账户后重试。', RATE_LIMITED: '操作过于频繁，请稍后再试。', INVITE_INVALID: '邀请凭证不匹配、已失效或已使用。请用受邀邮箱登录。', SEAT_LIMIT: '当前套餐席位不足。', ALREADY_MEMBER: '你已加入该空间。', ORDER_STATE_CONFLICT: '订单已过期或状态发生变化，请刷新。', VERSION_CONFLICT: '数据已被更新，请刷新后操作。', TENANT_SUSPENDED: '此空间已暂停，暂不允许修改或支付。', PROTECTED_ADMIN: '不能通过此入口停用当前账号或平台管理员。', CAPACITY_REACHED: '本地验证环境容量已达上限。', IDEMPOTENCY_CONFLICT: '重复请求的内容不一致，请重新发起。' };
function clearCheckout() { price.value = null; selectedOrder.value = null; payAcknowledged.value = false; orderRequestId = crypto.randomUUID(); }
Object.assign(errors, { PROVISIONING_REQUIRES_SANDBOX_APPROVAL: '请先完成测试空间审核。', PROVISIONING_ALREADY_EXISTS: '已有进行中的申请，请刷新查看。', PROVISIONING_NOT_FOUND: '申请不存在或不属于当前空间。', PROVISIONING_CONFIRMATION_REQUIRED: '请先确认预检说明。' });
const viewScope = () => JSON.stringify([workspace.value?.user.id || '', tenantId.value, tenant.value?.role || '', tenant.value?.status || '']);
function clearTenantView() {
  clearCheckout(); inviteToken.value = ''; acceptToken.value = ''; alert.value = ''; notice.value = '';
  invite.value = { email: '', role: 'member' }; billing.value.couponCode = ''; payMethod.value = 'sandbox';
}
watch(viewScope, clearTenantView, { flush: 'sync' });
function tenantInputChanged() { tenantForm.value.requestId = crypto.randomUUID(); }
function focusMain() { document.getElementById('main')?.focus(); }
function go(page) { if (busy.value) return; location.hash = `/${page}`; menuOpen.value = false; }
function changedRoute() {
  const next = parsePortalHash(location.hash); const samePage = route.value === next.page;
  route.value = next.page; documentRoute.value = next; menuOpen.value = false;
  alert.value = ''; notice.value = '';
  if (!samePage) { inviteToken.value = ''; clearCheckout(); }
  if (next.page !== 'docs') window.scrollTo(0, 0);
  document.title = `${({ home: '企业 Agent 与语义智能平台', product: '智脑工作台', semantic: '元域智语 Agent', demo: '双 Agent 交互案例', architecture: '平台架构', docs: '技术文档', pricing: '方案与交付', console: '客户中心', billing: '订阅与账单', team: '团队管理', admin: '平台运营', 'not-found': '页面未找到' })[route.value] || '账号'} · 元域`;
  if (route.value === 'admin' && workspace.value?.user.platformAdmin) run(loadAdmin);
}
async function run(work) {
  if (busy.value) return;
  const startingScope = viewScope(); const startingRoute = route.value;
  const startedInTenant = Boolean(workspace.value?.user.id && tenantId.value);
  busy.value = true; alert.value = ''; notice.value = '';
  try { await work(); } catch (e) {
    alert.value = errors[e.code] || '操作未完成，请稍后重试。没有执行真实收款。';
    if (e.status === 401) { workspace.value = null; admin.value = null; inviteToken.value = ''; setCsrf(''); }
    if (e.code === 'CSRF_REJECTED') { try { await refresh(); } catch { workspace.value = null; admin.value = null; } }
  } finally {
    // Includes refresh removing a membership, and browser back/hash changes while
    // a request is pending. A completed old request must not restore stale UI.
    if (startedInTenant && (startingScope !== viewScope() || startingRoute !== route.value)) clearTenantView();
    busy.value = false;
  }
}
async function refresh() { workspace.value = await portalRequest('me'); if (!workspace.value.tenants.some(t => t.id === tenantId.value)) tenantId.value = workspace.value.tenants[0]?.id || ''; }
async function loadAdmin() { admin.value = await portalRequest('admin'); }
function submitAuth(register) { run(async () => {
  if (register) { await portalRequest('register', auth.value); notice.value = '注册成功，请登录。邮箱尚未验证。'; auth.value.password = ''; route.value = 'login'; history.replaceState(null, '', '#/login'); return; }
  await portalRequest('login', { email: auth.value.email, password: auth.value.password }); auth.value.password = ''; await refresh(); route.value = 'console'; location.hash = '/console';
}); }
function logout() { run(async () => { await portalRequest('logout', {}); workspace.value = null; admin.value = null; inviteToken.value = ''; clearCheckout(); setCsrf(''); route.value = 'home'; location.hash = '/home'; }); }
function createTenant() { run(async () => { const result = await portalRequest('tenant/create', tenantForm.value); tenantId.value = result.tenantId; tenantForm.value = { name: '', slug: '', requestId: crypto.randomUUID() }; await refresh(); notice.value = '已创建开通申请和管理空间，等待平台审核。未部署业务实例。'; }); }
function requestProvisioning(requestId) { run(async () => {
  await portalRequest('tenant/provision', { tenantId: tenantId.value, requestId, expectedVersion: tenant.value.version, confirmed: true });
  await refresh(); notice.value = '预检申请已记录，等待运维检查。没有创建业务实例。';
}); }
function cancelProvisioning(provisioningId) { run(async () => {
  await portalRequest('tenant/provision-cancel', { tenantId: tenantId.value, provisioningId });
  await refresh(); notice.value = '预检申请已取消。不会删除模型或业务数据。';
}); }
function cents(value) { if (!/^\d{1,6}(\.\d{1,2})?$/.test(String(value))) throw { code: 'INVALID_AMOUNT' }; const [whole, fraction = ''] = String(value).split('.'); return Number(whole) * 100 + Number(fraction.padEnd(2, '0')); }
function orderBody() { return { tenantId: tenantId.value, kind: billing.value.kind, ...(billing.value.kind === 'recharge' ? { amountCents: cents(billing.value.amount) } : { planId: billing.value.planId, ...(billing.value.couponCode.trim() ? { couponCode: billing.value.couponCode.trim() } : {}) }) }; }
function quoteOrder() { run(async () => { price.value = (await portalRequest('order/quote', orderBody())).quote; }); }
function createOrder() { run(async () => { const result = await portalRequest('order/create', { ...orderBody(), requestId: orderRequestId }); selectedOrder.value = result.order; payAcknowledged.value = false; price.value = null; await refresh(); notice.value = '订单已生成，请核对应付金额。这是测试订单。'; }); }
function payOrder() { run(async () => { if (!payAcknowledged.value) return; await portalRequest('order/pay', { orderId: selectedOrder.value.id, method: payMethod.value, confirmed: true }); clearCheckout(); await refresh(); notice.value = '测试订单已入账。未真实收款，也未授予企业数据权限。'; }); }
function cancelOrder(order) { run(async () => { await portalRequest('order/cancel', { orderId: order.id }); clearCheckout(); await refresh(); notice.value = '订单已取消。'; }); }
function selectOrder(order) { selectedOrder.value = order; payMethod.value = 'sandbox'; payAcknowledged.value = false; }
function createInvite() { run(async () => { const data = await portalRequest('tenant/invite', { tenantId: tenantId.value, ...invite.value }); inviteToken.value = data.invitationToken; notice.value = '邀请凭证已生成，24小时有效。请通过可信渠道交给受邀人；未发送邮件。'; }); }
function acceptInvite() { run(async () => { const result = await portalRequest('invite/accept', { token: acceptToken.value.trim() }); acceptToken.value = ''; tenantId.value = result.tenantId; await refresh(); notice.value = '已加入受邀空间。'; }); }
function memberChange(member, remove = false) {
  if (remove && !window.confirm(`确定从此空间移除 ${member.name}？`)) return;
  run(async () => { await portalRequest('tenant/member', { tenantId: tenantId.value, userId: member.userId, role: remove ? member.role : member.role === 'admin' ? 'member' : 'admin', status: remove ? 'removed' : 'active', expectedVersion: tenant.value.version }); await refresh(); });
}
function adminChange(path, body) { run(async () => { await portalRequest(`admin/${path}`, body); await refresh(); await loadAdmin(); notice.value = '已更新。'; }); }
function createCoupon() { run(async () => { await portalRequest('admin/coupon', { code: coupon.value.code, type: coupon.value.type, value: cents(coupon.value.value), minCents: cents(coupon.value.min), maxUses: Number(coupon.value.maxUses), startsAt: Date.now(), expiresAt: Date.now() + Number(coupon.value.days) * 86400000, planId: coupon.value.planId || null }); await loadAdmin(); notice.value = '优惠券已创建，优惠金额由服务端核算。'; }); }
onMounted(async () => { window.addEventListener('hashchange', changedRoute); changedRoute(); await run(async () => { catalog.value = await portalRequest('catalog'); try { await refresh(); if (route.value === 'admin' && workspace.value.user.platformAdmin) await loadAdmin(); } catch (e) { if (e.status !== 401) throw e; } }); });
onUnmounted(() => window.removeEventListener('hashchange', changedRoute));
</script>

<template>
  <a class="skip-link" href="#main" @click.prevent="focusMain">跳到正文</a>
  <header class="site-header">
    <a class="brand" href="#/home" aria-label="元域首页"><img src="/favicon.svg" alt=""/><strong>元域<span>YUANYU</span></strong></a>
    <button class="mobile-menu" :aria-expanded="menuOpen" aria-controls="site-navigation" @click="menuOpen = !menuOpen">菜单</button>
    <nav id="site-navigation" :class="{ open: menuOpen }" aria-label="主导航"><a href="#/product" :aria-current="route === 'product' ? 'page' : undefined">智脑工作台</a><a href="#/semantic" :aria-current="route === 'semantic' ? 'page' : undefined">元域智语</a><a href="#/demo" :aria-current="route === 'demo' ? 'page' : undefined">场景演示</a><a href="#/architecture" :aria-current="route === 'architecture' ? 'page' : undefined">平台架构</a><a href="#/docs/overview" :aria-current="route === 'docs' ? 'page' : undefined">技术文档</a><a href="#/pricing" :aria-current="route === 'pricing' ? 'page' : undefined">方案与交付</a></nav>
    <div class="header-account"><template v-if="workspace"><button class="text-button" :disabled="busy" @click="go('console')">{{ workspace.user.name }}</button><button class="button small" :disabled="busy" @click="go('console')">客户中心 ↗</button></template><template v-else><a class="login-link" href="#/login">登录</a><a class="button small" href="#/demo">查看演示 ↗</a></template></div>
  </header>
  <div class="preview-strip">产品化预览 · 测试价格与测试支付 · 尚未开放生产服务</div>
  <div v-if="alert" class="global-message error" role="alert">{{ alert }}</div><div v-if="notice" class="global-message success" role="status">{{ notice }}</div>
  <div v-if="busy" class="loading-bar" role="status" aria-label="正在处理"/>

  <main id="main" tabindex="-1">
    <WebsitePages v-if="publicPages.includes(route)" :key="route" :page="route" :logged-in="Boolean(workspace)"/>
    <DocsCenter v-else-if="route === 'docs'" :selection="documentRoute"/>
    <section v-else-if="route === 'not-found'" class="wrap portal-not-found"><p class="eyebrow">404 / PAGE NOT FOUND</p><h1>这个页面暂不存在。</h1><p>请检查链接，或从产品首页继续浏览。</p><a class="button" href="#/home">返回首页 →</a></section>

    <section v-else-if="['login', 'register'].includes(route) || isConsole && !workspace" class="wrap auth-layout section-space"><div class="auth-intro"><p class="eyebrow">YOUR WORK, CONNECTED.</p><h1>每个企业，<br/>都有自己的业务世界。</h1><p>创建你的元域账号，管理空间、成员与订阅。业务数据权限始终由企业另行授权。</p><div class="auth-line">元域 / 产品客户中心</div></div><form class="panel auth-form" @submit.prevent="submitAuth(route === 'register')"><h2>{{ route === 'register' ? '创建元域账号' : '欢迎回来' }}</h2><p>{{ route === 'register' ? '账号用于本地产品化验证，尚未接入邮箱验证。' : '登录你的客户中心。' }}</p><label v-if="route === 'register'">你的姓名<input v-model="auth.name" autocomplete="name" maxlength="60" required/></label><label>邮箱<input v-model="auth.email" type="email" autocomplete="username" maxlength="254" required/></label><label>密码<input v-model="auth.password" type="password" :autocomplete="route === 'register' ? 'new-password' : 'current-password'" minlength="12" maxlength="128" required/><small>12至128位。测试环境请勿使用真实常用密码。</small></label><label v-if="route === 'register'" class="check"><input v-model="auth.acceptedTerms" type="checkbox" required/><span>我已阅读<a href="#/terms" target="_blank" rel="noopener">测试服务说明</a>与<a href="#/privacy" target="_blank" rel="noopener">数据说明</a>。</span></label><button class="button full" :disabled="busy">{{ busy ? '正在处理…' : route === 'register' ? '创建账号' : '登录' }}</button><p class="auth-switch"><a :href="route === 'register' ? '#/login' : '#/register'">{{ route === 'register' ? '已有账号？前往登录' : '还没有账号？创建账号' }}</a></p><small>密码找回、手机号与企业SSO登录尚未开放。</small></form></section>

    <div v-else-if="isConsole && workspace" class="console-layout wrap">
      <aside class="console-sidebar"><p class="eyebrow">CUSTOMER WORKSPACE</p><h2>客户中心</h2><label>当前空间<select v-model="tenantId" :disabled="busy" @change="clearCheckout(); inviteToken = ''"><option v-if="!workspace.tenants.length" value="">尚未创建空间</option><option v-for="item in workspace.tenants" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><nav aria-label="客户中心导航"><a href="#/console" :class="{ active: route === 'console' }">概览与开通 <span>01</span></a><a href="#/billing" :class="{ active: route === 'billing' }">订阅与账单 <span>02</span></a><a href="#/team" :class="{ active: route === 'team' }">团队与成员 <span>03</span></a><a v-if="workspace.user.platformAdmin" href="#/admin" :class="{ active: route === 'admin' }">平台运营 <span>04</span></a></nav><div class="account-detail"><b>{{ workspace.user.name }}</b><span>{{ workspace.user.email }}</span><small>邮箱未验证 · 本地测试账号</small><button class="text-button" :disabled="busy" @click="logout">退出登录</button></div></aside>
      <section class="console-content"><div class="console-title"><div><p class="eyebrow">YUANYU / CONTROL PLANE</p><h1>{{ { console: '你的元域空间', billing: '订阅与账单', team: '一起构建业务世界', admin: '平台运营' }[route] }}</h1></div><button class="button secondary small" :disabled="busy" @click="run(async () => { await refresh(); if (route === 'admin') await loadAdmin(); })">刷新</button></div><div class="callout compact">当前为本地商业管理测试环境。订单和余额不代表真实资金，空间开通不等于已连接生产智脑。</div>
        <ProvisioningPanel v-if="route === 'console' && tenant" :key="viewScope() + ':' + tenant.version + ':' + tenant.provisioning?.id + ':' + tenant.provisioning?.status" :tenant="tenant" :busy="busy" @request="requestProvisioning" @cancel="cancelProvisioning"/>
<template v-if="route === 'console'"><div v-if="tenant" class="metric-grid"><article><span>当前空间</span><b>{{ tenant.name }}</b><small>{{ status(tenant.status) }}</small></article><article><span>会员方案</span><b>{{ tenant.plan.name }}</b><small>{{ tenant.membership ? '到期：' + date(tenant.membership.expiresAt) : '未购买测试会员' }}</small></article><article><span>协作成员</span><b>{{ tenant.members.length }} <small>/ {{ tenant.plan.seats }}席位</small></b><small>{{ roleName(tenant.role) }}</small></article></div><div v-if="tenant" class="panel provision-panel"><div><p class="eyebrow">WORKSPACE PROVISIONING</p><h2>从管理空间，到企业工作台</h2><p>空间标识：{{ tenant.slug }}</p></div><ol class="provision-steps"><li class="complete"><b>1</b>创建管理空间</li><li :class="{ complete: tenant.status === 'sandbox_ready' }"><b>2</b>平台审核与测试开通</li><li><b>3</b>企业IAM与运行环境接入</li></ol><p>生产实例尚未连接。此处不会把普通注册账号映射到现有企业管理员，也不会开放企业数据。</p></div><div class="two-columns"><form class="panel" @submit.prevent="createTenant"><h2>{{ tenant ? '申请另一个空间' : '创建第一个空间' }}</h2><label>企业或团队名称<input v-model="tenantForm.name" maxlength="80" required :disabled="busy" @input="tenantInputChanged()"/></label><label>空间标识<input v-model="tenantForm.slug" placeholder="your-company" minlength="3" maxlength="40" pattern="[a-z][a-z0-9\-]{2,39}" required :disabled="busy" @input="tenantInputChanged()"/><small>唯一标识，3至40位字母、数字与短横线。</small></label><button class="button" :disabled="busy">提交开通申请 ↗</button></form><form class="panel" @submit.prevent="acceptInvite"><h2>加入已有团队</h2><p>请使用受邀邮箱登录，并填写管理员通过可信渠道交给你的邀请凭证。</p><label>邀请凭证<input v-model="acceptToken" autocomplete="off" maxlength="100" required/></label><button class="button secondary" :disabled="busy">接受邀请</button><p class="muted">邀请24小时有效且仅可使用一次。此处不提供公开的邀请码列表。</p></form></div></template>

        <template v-else-if="route === 'billing'"><div v-if="!tenant" class="empty-state"><h2>先创建一个企业空间</h2><p>会员、余额与订单归属于租户，而不是个人聊天账号。</p><a class="button" href="#/console">创建空间</a></div><div v-else-if="!canManage" class="empty-state">当前角色没有账单管理权限，请联系空间所有者。</div><template v-else><div class="metric-grid"><article><span>测试余额</span><b>{{ money(tenant.balanceCents) }}</b><small>不可提现 · 非真实资金</small></article><article><span>当前方案</span><b>{{ tenant.plan.name }}</b><small>{{ tenant.membership ? date(tenant.membership.expiresAt) + '到期' : '探索空间' }}</small></article><article><span>账单记录</span><b>{{ tenantOrders.length }}</b><small>仅显示当前空间</small></article></div><div class="two-columns"><form class="panel" @submit.prevent="quoteOrder"><h2>订阅或充值</h2><label>订单类型<select v-model="billing.kind" :disabled="busy" @change="clearCheckout"><option value="subscription">会员订阅 / 同套餐续费</option><option value="recharge">充值测试余额</option></select></label><template v-if="billing.kind === 'subscription'"><label>会员套餐<select v-model="billing.planId" :disabled="busy" @change="clearCheckout"><option v-for="plan in catalog.plans.filter(p => p.priceCents)" :key="plan.id" :value="plan.id">{{ plan.name }} · {{ money(plan.priceCents) }} / 30天</option></select></label><label>优惠券代码（可选）<input v-model="billing.couponCode" maxlength="32" :disabled="busy" @input="clearCheckout"/></label></template><label v-else>充值金额（测试元）<input v-model="billing.amount" inputmode="decimal" :disabled="busy" @input="clearCheckout"/></label><button class="button secondary" :disabled="busy">计算应付金额</button><div v-if="price" class="quote-summary"><p>原价 <b>{{ money(price.subtotalCents) }}</b></p><p>{{ { none: '无折扣', membership: '会员折扣', coupon: '优惠券减免' }[price.discountSource] }} <b>−{{ money(price.discountCents) }}</b></p><p class="quote-total">测试应付 <b>{{ money(price.totalCents) }}</b></p><small>会员折扣与优惠券不叠加，创建订单时会重新核验名额与有效期。</small><button type="button" class="button full" :disabled="busy" @click="createOrder">创建测试订单</button></div></form><div class="panel"><template v-if="selectedOrder"><p class="eyebrow">ORDER REVIEW</p><h2>核对测试订单</h2><p class="mono">{{ selectedOrder.number }}</p><div class="checkout-amount">{{ money(selectedOrder.totalCents) }}</div><p>有效至 {{ date(selectedOrder.expiresAt) }}</p><label>支付方式<select v-model="payMethod" :disabled="busy"><option value="sandbox">模拟支付（不真实扣款）</option><option v-if="selectedOrder.kind === 'subscription'" value="wallet">使用本租户测试余额</option></select></label><label class="check"><input v-model="payAcknowledged" type="checkbox" :disabled="busy"/><span>已核对当前订单金额，确认进行测试支付。未真实收款。</span></label><button class="button full" :disabled="busy || !payAcknowledged || !workspace.sandboxPayments" @click="payOrder">确认测试支付</button><p v-if="!workspace.sandboxPayments">测试支付开关尚未启用。</p></template><template v-else><p class="eyebrow">CLEAR BEFORE YOU PAY</p><h2>先核对，再入账。</h2><p>订单金额由服务端计算，不能从浏览器修改。每笔测试余额变化都有订单和流水依据。</p><ul class="plain-list"><li>订单30分钟有效</li><li>充值不能使用优惠券</li><li>会员与优惠券择优，不叠加</li><li>不自动续费，不开放真实收款</li></ul><a href="#/docs/billing">阅读计费规则 ↗</a></template></div></div><section class="panel"><h2>订单记录</h2><p v-if="!tenantOrders.length" class="muted">还没有订单。</p><div v-else class="table-scroll"><table><thead><tr><th>订单</th><th>类型</th><th>应付</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="order in tenantOrders" :key="order.id"><td><span class="mono">{{ order.number }}</span><small>{{ date(order.createdAt) }}</small></td><td>{{ order.kind === 'recharge' ? '测试充值' : '会员订阅' }}</td><td>{{ money(order.totalCents) }}</td><td><span class="badge">{{ status(order.status) }}</span></td><td><template v-if="order.status === 'pending'"><button class="text-button" :disabled="busy" @click="selectOrder(order)">支付</button><button class="text-button" :disabled="busy" @click="cancelOrder(order)">取消</button></template><span v-else>—</span></td></tr></tbody></table></div></section><section class="panel"><h2>余额流水</h2><p v-if="!tenantLedger.length" class="muted">暂无余额变动。</p><div v-else class="ledger-list"><div v-for="row in tenantLedger" :key="row.id"><span>{{ date(row.at) }}</span><b>{{ row.deltaCents > 0 ? '+' : '' }}{{ money(row.deltaCents) }}</b><span>余额 {{ money(row.balanceAfterCents) }}</span></div></div></section></template></template>

        <template v-else-if="route === 'team'"><div v-if="!tenant" class="empty-state"><h2>尚未加入空间</h2><a href="#/console">创建空间或接受邀请 ↗</a></div><template v-else><section class="panel"><h2>空间成员 <small>{{ tenant.members.length }} / {{ tenant.plan.seats }}</small></h2><div class="table-scroll"><table><thead><tr><th>成员</th><th>角色</th><th>操作</th></tr></thead><tbody><tr v-for="member in tenant.members" :key="member.userId"><td>{{ member.name }}<small>{{ member.email || '邮箱仅管理者可见' }}</small></td><td>{{ roleName(member.role) }}</td><td><template v-if="tenant.role === 'owner' && member.role !== 'owner'"><button class="text-button" :disabled="busy" @click="memberChange(member)">{{ member.role === 'admin' ? '改为成员' : '设为管理员' }}</button><button class="text-button danger" :disabled="busy" @click="memberChange(member, true)">移除</button></template><span v-else>—</span></td></tr></tbody></table></div></section><form v-if="canManage" class="panel narrow-panel" @submit.prevent="createInvite"><h2>邀请团队成员</h2><label>受邀人邮箱<input v-model="invite.email" type="email" maxlength="254" required/></label><label>空间角色<select v-model="invite.role"><option value="member">成员</option><option v-if="tenant.role === 'owner'" value="admin">管理员</option></select></label><button class="button" :disabled="busy">生成邀请凭证</button><div v-if="inviteToken" class="callout"><p>只在此处展示，请保密并交给受邀人。未发送邮件。</p><code class="secret-display">{{ inviteToken }}</code></div></form></template></template>

        <template v-else-if="route === 'admin'"><div v-if="!workspace.user.platformAdmin" class="empty-state">你没有平台运营权限。公开注册不会自动获得管理员资格。</div><template v-else-if="admin"><div class="metric-grid"><article><span>注册账号</span><b>{{ admin.users.length }}</b></article><article><span>租户开通记录</span><b>{{ admin.tenants.length }}</b></article><article><span>订单数</span><b>{{ admin.orderStats.count }}</b><small>所有金额均为测试资金</small></article></div><section class="panel"><h2>租户开通管理</h2><p>测试开通仅改变管理空间状态；生产IAM、存储与模型环境尚未自动部署。</p><div class="table-scroll"><table><thead><tr><th>企业空间</th><th>状态</th><th>成员</th><th>操作</th></tr></thead><tbody><tr v-for="item in admin.tenants" :key="item.id"><td>{{ item.name }}</td><td>{{ status(item.status) }}</td><td>{{ item.memberCount }}</td><td><button class="text-button" :disabled="busy || item.status === 'sandbox_ready'" @click="adminChange('tenant', { tenantId: item.id, status: 'sandbox_ready', expectedVersion: item.version })">开通测试空间</button><button class="text-button danger" :disabled="busy || item.status === 'suspended'" @click="adminChange('tenant', { tenantId: item.id, status: 'suspended', expectedVersion: item.version })">暂停</button></td></tr></tbody></table></div></section><section class="panel"><h2>用户管理</h2><div class="table-scroll"><table><thead><tr><th>用户</th><th>身份</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="user in admin.users" :key="user.id"><td>{{ user.name }}<small>{{ user.email }}</small></td><td>{{ user.platformAdmin ? '平台管理员' : '客户账号' }}</td><td>{{ status(user.status) }}</td><td><button v-if="!user.platformAdmin" class="text-button" :disabled="busy" @click="adminChange('user', { userId: user.id, status: user.status === 'active' ? 'suspended' : 'active' })">{{ user.status === 'active' ? '停用' : '启用' }}</button><span v-else>受保护</span></td></tr></tbody></table></div></section><form class="panel" @submit.prevent="createCoupon"><h2>创建优惠券</h2><div class="form-grid"><label>券代码<input v-model="coupon.code" minlength="3" maxlength="32" pattern="[A-Za-z0-9_\-]{3,32}" required/></label><label>优惠方式<select v-model="coupon.type"><option value="fixed">固定金额减免</option><option value="percent">比例减免</option></select></label><label>{{ coupon.type === 'fixed' ? '减免金额（元）' : '减免百分比（10代表9折）' }}<input v-model="coupon.value" inputmode="decimal" required/></label><label>最低订单金额（元）<input v-model="coupon.min" inputmode="decimal" required/></label><label>可用次数<input v-model="coupon.maxUses" type="number" min="1" max="10000" required/></label><label>有效天数<input v-model="coupon.days" type="number" min="1" max="365" required/></label><label>适用方案<select v-model="coupon.planId"><option value="">所有付费套餐</option><option v-for="plan in catalog.plans.filter(p => p.priceCents)" :key="plan.id" :value="plan.id">{{ plan.name }}</option></select></label></div><button class="button" :disabled="busy">创建优惠券</button></form><section class="panel"><h2>优惠券管理</h2><p v-if="!admin.coupons.length" class="muted">尚未创建优惠券。</p><div v-else class="table-scroll"><table><thead><tr><th>代码</th><th>优惠</th><th>有效至</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in admin.coupons" :key="item.id"><td class="mono">{{ item.code }}</td><td>{{ item.type === 'fixed' ? money(item.value) : '减免' + item.value / 100 + '%' }}</td><td>{{ date(item.expiresAt) }}</td><td>{{ item.active ? '启用' : '停用' }}</td><td><button :disabled="busy || !item.active" class="text-button" @click="adminChange('coupon-disable', { couponId: item.id })">停用并取消相关待支付订单</button></td></tr></tbody></table></div></section><section class="panel"><h2>最近操作审计</h2><div class="audit-list"><div v-for="entry in admin.audits" :key="entry.id"><b>{{ entry.action }}</b><span>{{ date(entry.at) }}</span><small>{{ entry.targetId }}</small></div></div></section></template></template>
      </section>
    </div>

    <article v-else-if="route === 'terms' || route === 'privacy'" class="wrap legal-page section-space"><p class="eyebrow">LOCAL PRODUCT PREVIEW</p><h1>{{ route === 'terms' ? '测试服务说明' : '数据与隐私说明' }}</h1><template v-if="route === 'terms'"><h2>仅用于产品化验证</h2><p>当前网站为元域本地开发验证版本，不是已上线的商业服务。展示的价格是测试样例，不构成正式报价。充值和会员支付均为模拟，不会从微信、支付宝或银行卡扣款，也不能提现。</p><h2>能力与授权范围</h2><p>管理空间、成员与会员记录不等于企业业务数据访问权。生产智脑、元域智语及第三方系统接入，需要独立配置、授权和验收。</p><h2>正式服务前</h2><p>正式运营主体、服务协议、退款规则、发票、服务等级与投诉渠道尚未发布。当前说明不代替经审核的生产合同。请勿以本环境处理真实资金或商业承诺。</p></template><template v-else><h2>本地保存哪些内容</h2><p>注册邮箱、姓名、加盐密码哈希、会话摘要、租户成员、订单、优惠券和审计记录，保存在本机产品门户数据库中。此门户不调用大模型处理账号资料，不复制现有企业业务库。</p><h2>请使用测试信息</h2><p>邮箱验证、密码找回、账号删除及数据留存自动清理尚未接入。不要提交真实敏感资料，不要复用日常密码。邀请凭证具有加入团队的作用，请通过可信渠道转交。</p><h2>上线前需补全</h2><p>正式运营主体、个人信息处理政策、权利申请渠道、保存期限、删除流程、Cookie说明及委托处理清单需要根据实际部署审核。本页如实说明本地验证行为，不宣称已完成合规审查。</p></template><a href="#/register">返回注册 ↗</a></article>
  </main>
